      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-which\",\n  \"version\": \"0.1.0\",\n  \"description\": \"Command resolution forensics for DeepSeek Harness: what actually runs when a command is typed 鈥?which PATH entry wins, what it shadowed, what shape PATH is in, and whether the copies behind one name agree on a version.\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": {\n      \"default\": \"./lib/index.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./icon\": \"./icon.svg\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\",\n    \"locale\",\n    \"icon.svg\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"LICENSE\",\n    \"scripts\"\n  ],\n  \"scripts\": {\n    \"test\": \"node --test \\\"test/**/*.test.mjs\\\"\",\n    \"test:live\": \"node test/live-which.mjs\",\n    \"setup:deps\": \"node scripts/link-host-deps.mjs\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"which\",\n    \"path\",\n    \"pathext\",\n    \"command-resolution\",\n    \"shadowing\",\n    \"environment\",\n    \"diagnostics\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/11111353535/dsh-which.git\"\n  },\n  \"homepage\": \"https://github.com/11111353535/dsh-which#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/11111353535/dsh-which/issues\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"license\": \"MIT\"\n}\n"
